"use strict";
const $=s=>document.querySelector(s), esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
let config=null,current=null,sweepResult=null,caseList=[],comparison=null,context={},tab="states",generation=0,dirty=true,busy=false;
const fmt=(v,d=2)=>v===null||v===undefined?"—":Number(v).toLocaleString("ja-JP",{maximumFractionDigits:d,minimumFractionDigits:d});
const time=v=>new Date(v).toLocaleString("ja-JP");
function notify(message,error=false){const el=$("#toast");el.textContent=message;el.className="visible"+(error?" error":"");clearTimeout(notify.timer);notify.timer=setTimeout(()=>el.className="",5000);}
async function api(path,data){const response=await fetch(path,data===undefined?{}:{method:"POST",headers:{"Content-Type":"application/json","X-Cycle-Token":$('meta[name="cycle-token"]').content},body:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw new Error(result.error||"処理できませんでした。");return result;}
function download(name,text,type="application/json"){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement("a");a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function panel(title,body,extra=""){return `<section class="panel"><div class="panel-head"><h2>${title}</h2>${extra}</div>${body}</section>`;}
function empty(text){return `<div class="empty">${text}</div>`;}
function initializeFields(){const groups=[...new Set(config.fields.map(x=>x.group))];$("#fields").innerHTML=groups.map((g,i)=>`<details ${i<2?"open":""}><summary>${esc(g)}</summary>${config.fields.filter(x=>x.group===g).map(f=>`<label class="field" for="${f.key}">${esc(f.label)}<div class="number-input"><input type="number" id="${f.key}" name="${f.key}" aria-label="${esc(f.label)}" min="${f.min}" max="${f.max}" step="any" required><span class="unit">${esc(f.unit)}</span></div></label>`).join("")}</details>`).join("");}
function modeFields(){const target=$("#mode").value==="target_power";$("#air_mass_flow_kg_s").disabled=target;$("#target_net_power_w").disabled=!target;$("#mode-note").textContent=target?"必要流量は計算後の状態表に表示します。無効な空気流量欄の保存値は、この計算には使用しません。":"指定流量で計算します。無効な目標出力欄は使用しません。";for(const key of ["air_mass_flow_kg_s","target_net_power_w"]){if(!$("#"+key).value)$("#"+key).value=config.fields.find(x=>x.key===key).default;}}
function thermoLabel(input){return input?.thermodynamics?.model==="nasa9_frozen"?"NASA9 温度依存":"比熱一定";}
function thermoFields(){const nasa=$("#thermo-model").value==="nasa9_frozen";for(const key of ["cp_air_j_kg_k","cp_gas_j_kg_k","r_air_j_kg_k","r_gas_j_kg_k"])$("#"+key).disabled=nasa;$("#fuel").disabled=!nasa;$("#fuel-h").disabled=!nasa||$("#fuel").value!=="custom_ch";$(".model-tag").textContent=nasa?"入力：NASA9 温度依存 / 凍結組成":"入力：比熱一定";$("#thermo-note").textContent=nasa?"NASA公式CEA係数を使用。乾燥空気・希薄完全燃焼。GasTurb独自表・燃焼の化学平衡・解離との一致は未検証です。LHVは独立入力で、燃料組成の変更では自動変更しません。":"旧モデルを保持します。燃料組成は使用せず、空気・ガスの比熱と気体定数を直接指定します。";}

function readStageList(selector,label){const text=$(selector).value.trim();if(!text)return null;const parts=text.split(/[,、\s]+/);if(parts.some(x=>!x||!Number.isFinite(Number(x))))throw new Error(label+"を正の数のカンマ区切りで入力してください。");return parts.map(Number);}
function collectStaging(){const result={};for(const [key,label] of [["compressor","圧縮機"],["turbine","タービン"]]){const count=Number($("#"+key+"-count").value);if(!Number.isInteger(count)||count<1||count>30)throw new Error(label+"の段数は1〜30の整数にしてください。");result[key]={count,distribution:$("#"+key+"-distribution").value,weights:readStageList("#"+key+"-weights",label+"の配分重み")||Array(count).fill(1),mean_diameters_m:readStageList("#"+key+"-diameters",label+"の段平均径")};}return result;}
function setStaging(staging){for(const key of ["compressor","turbine"]){const x=staging?.[key]||{count:1,distribution:"pressure",weights:[1],mean_diameters_m:null};$("#"+key+"-count").value=x.count;$("#"+key+"-distribution").value=x.distribution;$("#"+key+"-weights").value=x.weights.every(v=>v===x.weights[0])?"":x.weights.join(", ");$("#"+key+"-diameters").value=x.mean_diameters_m?.join(", ")||"";}}
function stagingLabel(input){return ["compressor","turbine"].map(k=>{const x=input?.staging?.[k];return (k==="compressor"?"圧縮機":"タービン")+(x?.count||1)+"段 / "+(x?.distribution==="work"?"仕事配分":"対数圧力配分")+(x?" / 重み["+x.weights.join(",")+"] / 径["+(x.mean_diameters_m?.join(",")||"未指定")+"]":"");}).join("、");}
function stageChart(x){const W=680,H=200,L=55,R=55,T=25,B=35,s=x.states,maxT=Math.ceil(Math.max(...s.map(x=>x.total_temperature_k))/100)*100,maxP=Math.ceil(Math.max(...s.map(x=>x.total_pressure_pa))/100000)*100;const px=i=>L+i*(W-L-R)/(s.length-1),ty=v=>H-B-v/maxT*(H-T-B),py=v=>H-B-v/maxP*(H-T-B);let plot="";for(let i=0;i<5;i++){const y=T+(H-T-B)*i/4;plot+=`<line class="grid-line" x1="${L}" x2="${W-R}" y1="${y}" y2="${y}"/><text x="${L-8}" y="${y+4}" text-anchor="end">${fmt(maxT*(4-i)/4,0)}</text><text x="${W-R+8}" y="${y+4}">${fmt(maxP*(4-i)/4,0)}</text>`;}plot+=`<polyline class="line temperature" points="${s.map((v,i)=>`${px(i)},${ty(v.total_temperature_k)}`).join(" ")}"/><polyline class="line pressure" points="${s.map((v,i)=>`${px(i)},${py(v.total_pressure_pa/1000)}`).join(" ")}"/>`;for(let i=0;i<s.length;i++){if(i===0||i===s.length-1||s.length<=11||i%Math.ceil((s.length-1)/8)===0)plot+=`<text x="${px(i)}" y="${H-9}" text-anchor="middle">${i===0?"入口":i+"段後"}</text>`;}return `<svg class="chart" role="img" aria-label="段間の全温と全圧" viewBox="0 0 ${W} ${H}"><text x="${L}" y="13">全温 K</text><text x="${W-R}" y="13" text-anchor="end">全圧 kPa</text>${plot}</svg>`;}
function renderStages(){const all=current.result.stage_results;if(!all){$("#details").innerHTML=empty("この旧版結果には段間性能がありません。再計算してください。");return;}$("#details").innerHTML=`<div class="notice">全体モードは全体効率・端点を固定した一定ポリトロープ経路での配分です。要素モードは段の全圧比と要素係数から仕事・実際の効率を再計算します。冷却は別設定の抽気・混合モデルを使用します。翼列形状・作動点は解析しません。</div>`+["compressor","turbine"].map(key=>{const x=all[key],c=key==="compressor",title=c?"圧縮機":"タービン";return panel(title+`：${x.count}段`, `<div class="panel-body"><div class="stage-summary"><span>全体ηtt <strong>${fmt(pct(x.recovered_overall_isentropic_efficiency),3)}%</strong></span><span>等価ηp <strong>${fmt(pct(x.polytropic_efficiency),3)}%</strong></span><span>${c?"圧縮比":"膨張比"} <strong>${fmt(x.overall_pressure_ratio,4)}</strong></span><span>${c?"圧縮機動力":"タービンガス仕事率"} <strong>${fmt(x.total_power_w/1000,3)} kW</strong></span></div><p class="minor">${x.distribution==="pressure"?"対数圧力比":"比仕事"}を指定重みで配分。${x.elements?"要素から計算した":"再構成した"}全体効率 ${fmt(pct(x.recovered_overall_isentropic_efficiency),6)}%。${x.elements?"等価ηpは全体端点からの比較値であり、一定ηpの経路は仮定しません。":""}タービンの機械伝達効率はガス仕事の外側で適用します。</p>${stageChart(x)}</div><div class="table-wrap"><table><thead><tr><th>段</th><th>入口 kg/s</th><th>出口 kg/s</th><th>入口T K</th><th>出口T K</th><th>入口P kPa</th><th>出口P kPa</th><th>${c?"圧縮比":"膨張比"}</th><th>比仕事 kJ/kg</th><th>${c?"消費動力":"ガス仕事率"} kW</th><th>段ηtt %</th><th>仕事配分 %</th><th>ln(PR)配分 %</th></tr></thead><tbody>${x.stages.map(s=>`<tr><td>${s.stage}</td><td class="num">${fmt(s.inlet.mass_flow_kg_s,6)}</td><td class="num">${fmt(s.outlet.mass_flow_kg_s,6)}</td><td class="num">${fmt(s.inlet.total_temperature_k,2)}</td><td class="num">${fmt(s.outlet.total_temperature_k,2)}</td><td class="num">${fmt(s.inlet.total_pressure_pa/1000,3)}</td><td class="num">${fmt(s.outlet.total_pressure_pa/1000,3)}</td><td class="num">${fmt(s.pressure_ratio,5)}</td><td class="num">${fmt(s.specific_work_j_kg/1000,3)}</td><td class="num">${fmt(s.power_w/1000,3)}</td><td class="num">${fmt(pct(s.isentropic_efficiency),4)}</td><td class="num">${fmt(s.work_fraction*100,3)}</td><td class="num">${fmt(s.pressure_log_fraction*100,3)}</td></tr>`).join("")}</tbody></table></div><div class="panel-body"><p class="minor">入口・出口は全温・全圧。比仕事は圧縮機では上昇量、タービンでは低下量を正で表示します。段仕事率の和と全体との差：${fmt(x.sum_stage_power_w-x.total_power_w,8)} W。</p></div><div class="table-wrap"><table><thead><tr><th>段</th><th>出口cp kJ/(kg K)</th><th>出口γ</th><th>Δs J/(kg K)</th><th>段平均径 m</th><th>周速U m/s</th><th>ψ=Δh/U²</th></tr></thead><tbody>${x.stages.map(s=>`<tr><td>${s.stage}</td><td class="num">${fmt(s.outlet.cp_j_kg_k/1000,5)}</td><td class="num">${fmt(s.outlet.gamma,6)}</td><td class="num">${fmt(s.entropy_generation_j_kg_k,5)}</td><td class="num">${fmt(s.mean_diameter_m,4)}</td><td class="num">${fmt(s.blade_speed_m_s,2)}</td><td class="num">${fmt(s.loading_coefficient,5)}</td></tr>`).join("")}</tbody></table></div><div class="panel-body"><p class="minor">ψは本アプリではΔh/U²（係数2を含まない定義）。径未指定時は周速・ψを未算出とします。反動度・流量係数・拡散係数・失速余裕は未算出で、ψから設計の適否を自動判定しません。</p></div>`);}).join("");}


let elementDraft=null;
function collectElements(){const result={};for(const key of ["compressor","turbine"]){const c=key==="compressor",label=c?"圧縮機":"タービン";const number=id=>{const text=$(id).value;if(!text.trim()||!Number.isFinite(Number(text)))throw new Error(label+"の要素係数・流速・効率を数値で入力してください。");return Number(text);};const rows=[...document.querySelectorAll(`[data-element-stage="${key}"]`)];result[key]={enabled:$("#element-"+key+"-enabled").checked,inlet_velocity_m_s:number("#element-"+key+"-inlet"),stages:rows.map((el,i)=>{const p="#e-"+key+"-"+i+"-",x={rotor_efficiency:number(p+"eta")/100,rotor_exit_velocity_m_s:number(p+"rotor-v")};for(const role of c?["diffuser","return_channel"]:["nozzle","diffuser"]){x[role]={enabled:$(p+role+"-on").checked,model:$(p+role+"-model").value,coefficient:number(p+role+"-coef"),exit_velocity_m_s:number(p+role+"-v")};}return x;})};}return result;}
function elementFields(){for(const key of ["compressor","turbine"]){const on=$("#element-"+key+"-enabled").checked;$("#"+key+"_efficiency").disabled=on;$("#"+key+"-distribution").disabled=on;$("#element-"+key+"-inlet").disabled=!on;document.querySelectorAll(`[data-element-stage="${key}"] input,[data-element-stage="${key}"] select`).forEach(el=>el.disabled=!on);}}
function renderElementInputs(){const box=$("#element-fields");box.innerHTML=["compressor","turbine"].map(key=>{const x=elementDraft[key],c=key==="compressor",label=c?"圧縮機":"タービン";return `<section class="element-machine"><div class="element-machine-head"><h3>${label}</h3><label><input type="checkbox" id="element-${key}-enabled" aria-label="${label}の要素モード" ${x.enabled?"checked":""}> 要素モードを使用</label><label class="field">機器入口流速 m/s<input type="number" id="element-${key}-inlet" aria-label="${label}の要素入口流速" value="${x.inlet_velocity_m_s}" min="1" max="600" step="any"></label></div><p class="minor">${c?"インペラー → ディフューザー → リターンチャネル（段ごと）":"ノズル → タービンロータ → 出口ディフューザー（段ごと）"}。全体モード時は下の値を計算に使いません。</p>${x.stages.map((row,i)=>{const p="e-"+key+"-"+i+"-",prefix=label+(i+1)+"段 ";const passive=(role,name)=>{const v=row[role];return `<tr><td><label><input type="checkbox" id="${p+role}-on" aria-label="${prefix+name}を使用" ${v.enabled?"checked":""}> ${name}</label></td><td><select id="${p+role}-model" aria-label="${prefix+name}の係数種類"><option value="cp" ${v.model==="cp"?"selected":""}>静圧回復 Cp</option><option value="loss" ${v.model==="loss"?"selected":""}>全圧損失 ζ</option></select></td><td><input type="number" id="${p+role}-coef" aria-label="${prefix+name}の係数" value="${v.coefficient}" step="any"></td><td><input type="number" id="${p+role}-v" aria-label="${prefix+name}の出口流速" value="${v.exit_velocity_m_s}" min="1" max="600" step="any"></td></tr>`;};return `<details data-element-stage="${key}" ${i===0?"open":""}><summary>${label} ${i+1}段の要素条件</summary><div class="table-wrap"><table class="element-editor"><thead><tr><th>要素・使用</th><th>指定方法</th><th>効率 %／係数</th><th>出口流速 m/s</th></tr></thead><tbody>${!c?passive("nozzle","ノズル"):""}<tr><td>${c?"インペラー":"タービンロータ"}</td><td>全圧等エントロピー効率</td><td><input type="number" id="${p}eta" aria-label="${prefix}ロータ効率" value="${row.rotor_efficiency*100}" min="50" max="100" step="any"></td><td><input type="number" id="${p}rotor-v" aria-label="${prefix}ロータ出口流速" value="${row.rotor_exit_velocity_m_s}" min="1" max="600" step="any"></td></tr>${passive("diffuser",c?"ディフューザー":"出口ディフューザー")}${c?passive("return_channel","リターンチャネル"):""}</tbody></table></div></details>`;}).join("")}</section>`;}).join("");elementFields();}
function setElements(value){elementDraft=structuredClone(value||config.default.elements);renderElementInputs();}
function resizeElementStages(){elementDraft=collectElements();for(const key of ["compressor","turbine"]){const count=Number($("#"+key+"-count").value);if(!Number.isInteger(count)||count<1||count>30)return;const rows=elementDraft[key].stages;while(rows.length<count)rows.push(structuredClone(config.element_stage_templates[key]));rows.length=count;}renderElementInputs();}
function elementLabel(input){return ["compressor","turbine"].map(key=>{const x=input?.elements?.[key];return (key==="compressor"?"圧縮機":"タービン")+"："+(x?.enabled?"要素モード（"+x.stages.length+"段）":"全体効率モード");}).join(" / ");}
function renderElements(){const all=current.result.stage_results;$("#details").innerHTML=`<div class="notice">Cpは静圧回復、ζは全圧損失。どちらも入口動圧q=ρV²/2基準です。圧縮性を考慮するためPt−pをqで置き換えません。静止要素は全温一定・仕事なし。ロータ効率は絶対系の全圧効率で、相対速度三角形は解きません。</div>`+["compressor","turbine"].map(key=>{const x=all[key],label=key==="compressor"?"圧縮機":"タービン";if(!x.elements)return panel(label,empty("全体効率モードです。上部「要素別性能・係数」で要素モードを有効にしてください。"));return panel(label+"の要素別状態",`<div class="panel-body"><div class="stage-summary"><span>${x.method==="cooled_element_network"?"冷却込み熱力学効率":"計算された全体ηtt"} <strong>${fmt(pct(x.method==="cooled_element_network"?x.thermodynamic_efficiency:x.recovered_overall_isentropic_efficiency),4)}%</strong></span><span>総仕事率 <strong>${fmt(x.total_power_w/1000,3)} kW</strong></span><span>出口全圧残差 <strong>${fmt(x.outlet_pressure_residual_pa,7)} Pa</strong></span></div><p class="minor">全体効率欄は未使用です。指定した段全圧比を満たすロータ圧力比を逆算しています。有効流路面積は入力流量・密度・流速からの換算値で、設計形状ではありません。</p></div><div class="table-wrap"><table><thead><tr><th>段・要素</th><th>Tt入口 K</th><th>Tt出口 K</th><th>静温出口 K</th><th>Pt入口 kPa</th><th>Pt出口 kPa</th><th>p入口 kPa</th><th>p出口 kPa</th><th>V出口 m/s</th><th>M出口</th><th>仕事率 kW</th></tr></thead><tbody>${x.elements.map(e=>`<tr><td>${e.stage} ${esc(e.name)}</td><td class="num">${fmt(e.inlet.total_temperature_k,2)}</td><td class="num">${fmt(e.outlet.total_temperature_k,2)}</td><td class="num">${fmt(e.outlet.static_temperature_k,2)}</td><td class="num">${fmt(e.inlet.total_pressure_pa/1000,3)}</td><td class="num">${fmt(e.outlet.total_pressure_pa/1000,3)}</td><td class="num">${fmt(e.inlet.static_pressure_pa/1000,3)}</td><td class="num">${fmt(e.outlet.static_pressure_pa/1000,3)}</td><td class="num">${fmt(e.outlet.velocity_m_s,2)}</td><td class="num">${fmt(e.outlet.mach,4)}</td><td class="num">${fmt(e.power_w/1000,3)}</td></tr>`).join("")}</tbody></table></div><div class="table-wrap"><table><thead><tr><th>段・要素</th><th>入力モデル</th><th>入力係数</th><th>入口q kPa</th><th>実際のCp</th><th>実際のζ</th><th>全圧損失 kPa</th><th>ロータηtt %</th><th>ロータPR</th><th>Δs J/(kg K)</th><th>出口有効面積 m²</th></tr></thead><tbody>${x.elements.map(e=>`<tr><td>${e.stage} ${esc(e.name)}</td><td>${e.coefficient_model==="cp"?"Cp":e.coefficient_model==="loss"?"ζ":e.kind==="mixing"?"冷却混合":"ロータ"}</td><td class="num">${fmt(e.specified_coefficient,5)}</td><td class="num">${fmt(e.inlet.dynamic_pressure_pa/1000,4)}</td><td class="num">${fmt(e.pressure_recovery_coefficient,5)}</td><td class="num">${fmt(e.total_pressure_loss_coefficient,5)}</td><td class="num">${fmt(e.total_pressure_loss_pa===null?null:e.total_pressure_loss_pa/1000,4)}</td><td class="num">${fmt(e.rotor_isentropic_efficiency===null?null:e.rotor_isentropic_efficiency*100,3)}</td><td class="num">${fmt(e.rotor_pressure_ratio,5)}</td><td class="num">${fmt(e.entropy_generation_j_kg_k,5)}</td><td class="num">${fmt(e.outlet.effective_flow_area_m2,6)}</td></tr>`).join("")}</tbody></table></div>`);}).join("");}


const pct=v=>v===null||v===undefined?null:v*100;
let coolingDraft=null;
function readCooling(){const number=id=>{const text=$(id).value;if(!text.trim()||!Number.isFinite(Number(text)))throw new Error("冷却流路の数値を入力してください。");return Number(text);};return {enabled:$("#cooling-enabled").checked,temperature_basis:$("#cooling-basis").value,combustor_exit_limit_k:number("#cooling-limit"),circuits:[...document.querySelectorAll("[data-cooling-index]")].map((el,i)=>{const p="#c-"+i+"-";return {name:$(p+"name").value,source_stage:number(p+"source"),target_stage:number(p+"target"),fraction:number(p+"fraction")/100,injection:$(p+"injection").value,pressure_loss_fraction:number(p+"loss")/100,heat_j_kg:number(p+"heat")*1000,mix_pressure_loss_fraction:number(p+"mixloss")/100,required_pressure_margin:number(p+"margin")/100,mixed_velocity_m_s:number(p+"velocity"),thermal:readBlade(i,"thermal"),pumping:readBlade(i,"pumping")};})};}
function coolingFields(){const on=$("#cooling-enabled").checked,basis=$("#cooling-basis").value;const label=on?(basis==="combustor_exit"?"燃焼器出口全温（冷却混合前）":"1段目ロータ入口全温（冷却混合後）"):config.fields.find(f=>f.key==="turbine_inlet_temperature_k").label;const el=$("#turbine_inlet_temperature_k");el.setAttribute("aria-label",label);document.querySelector('label[for="turbine_inlet_temperature_k"]').firstChild.textContent=label;$("#cooling-temp-note").textContent=on?(basis==="combustor_exit"?"設計条件の温度欄は燃焼器出口です。冷却混合後のロータ入口温度は結果で確認します。":"設計条件の温度欄は1段目ロータ入口です。上限以内の燃焼器出口温度と燃料流量を逆算します。")+" 全体ηttと冷却込み熱力学効率は区別します。":"冷却流路は使用せず、従来のサイクルとして計算します。";}
function renderCoolingInputs(){const x=coolingDraft;$("#cooling-enabled").checked=x.enabled;$("#cooling-basis").value=x.temperature_basis;$("#cooling-limit").value=x.combustor_exit_limit_k;$("#cooling-fields").innerHTML=x.circuits.map((c,i)=>{const p="c-"+i+"-",label="冷却流路"+(i+1)+" ";const field=(id,title,value,unit)=>`<label class="field">${title} ${unit}<input type="number" id="${p+id}" aria-label="${label+title}" value="${value}" step="any"></label>`;return `<details data-cooling-index="${i}" open><summary>冷却流路 ${i+1}：${esc(c.name)}</summary><div class="cooling-input-grid"><label class="field">流路名<input type="text" id="${p}name" aria-label="${label}流路名" value="${esc(c.name)}" maxlength="80"></label>${field("source","抽気する圧縮機段",c.source_stage,"段出口")}${field("fraction","抽気率",c.fraction*100,"%・入口空気基準")}${field("target","注入するタービン段",c.target_stage,"段")}<label class="field">混合位置<select id="${p}injection" aria-label="${label}混合位置">${[["before_nozzle","ノズル前"],["before_rotor","ロータ前"],["after_rotor","ロータ後"],["after_diffuser","出口ディフューザー後"]].map(([k,v])=>`<option value="${k}" ${k===c.injection?"selected":""}>${v}</option>`).join("")}</select></label>${field("loss","冷却流路の全圧損失率",c.pressure_loss_fraction*100,"%")}${field("heat","流路の外部熱授受",c.heat_j_kg/1000,"kJ/kg-coolant")}${field("mixloss","混合による主流全圧低下率",c.mix_pressure_loss_fraction*100,"%")}${field("margin","注入に必要な圧力余裕",c.required_pressure_margin*100,"%・局所静圧基準")}${field("velocity","混合後流速",c.mixed_velocity_m_s,"m/s")}</div>${bladeInputs(c,i)}<button class="button" type="button" data-remove-cooling="${i}">この冷却流路を削除</button></details>`;}).join("")||'<p class="minor">流路は未設定です。「冷却流路を追加」またはサンプル設定を使用してください。</p>';coolingFields();}
function setCooling(value){coolingDraft=structuredClone(value||config.default.cooling);renderCoolingInputs();}
function coolingLabel(input){const x=input?.cooling;return x?.enabled?"冷却あり / "+(x.temperature_basis==="first_rotor_inlet"?"ロータ入口温度指定":"燃焼器出口温度指定")+(x.circuits.some(c=>c.thermal?.enabled&&c.thermal.mode==="metal_limit")?" / 抽気合計入力値（逆算前） ":" / 抽気合計 ")+fmt(x.circuits.reduce((a,c)=>a+c.fraction,0)*100,3)+"%":"冷却なし";}
function renderCoolingBase(){const c=current.result.cooling,m=current.result.metrics;if(!c){$("#details").innerHTML=empty("冷却流量は0です。上部「冷却空気・抽気・混合」で流路を設定してください。");return;}const mixes=current.result.stage_results.turbine.elements.filter(e=>e.kind==="mixing");$("#details").innerHTML=panel("冷却空気と燃焼・タービンの流量",`<div class="panel-body"><div class="stage-summary"><span>入口空気 ${fmt(m.air_mass_flow_kg_s,6)} kg/s</span><span>燃焼器空気 ${fmt(m.combustor_air_mass_flow_kg_s,6)} kg/s</span><span>冷却空気 ${fmt(m.cooling_air_mass_flow_kg_s,6)} kg/s</span><span>冷却混合前ガス ${fmt(c.hot_turbine_mass_flow_kg_s,6)} kg/s</span><span>全冷却混合後ガス ${fmt(m.gas_mass_flow_kg_s,6)} kg/s</span></div><p>燃焼器出口 <strong>${fmt(m.combustor_exit_temperature_k,3)} K</strong> / 1段目ロータ入口 <strong>${fmt(m.first_rotor_inlet_temperature_k,3)} K</strong></p><p>冷却タービンの熱力学効率 <strong>${fmt(pct(m.turbine_thermodynamic_efficiency),4)}%</strong>。単一入口のηttと同じ指標ではありません。</p><p class="minor">熱力学効率＝（ガス仕事率−冷却ポンピング） /（主流と各冷却流の、個別全圧から共通出口圧までの等エントロピー仕事ポテンシャルの和）。ポンピングを含む場合は、ガス仕事率からポンピング仕事を引いた正味流体仕事を分子に使い、冷却流の仕事ポテンシャルはポンプ前の状態で評価します。段内混合がある段の単一入口ηttと、全体の等価ηpは未定義として表示します。</p><p class="minor">流路外部熱授受 ${fmt(c.external_heat_w/1000,4)} kW。外部加熱を含む入熱基準の発電効率 ${fmt(pct(m.electric_efficiency_total_heat),4)}%。燃料LHV効率とは基準を区別してください。</p></div>`)+panel("抽気・供給流路",`<div class="table-wrap"><table><thead><tr><th>流路</th><th>抽気段→注入段</th><th>混合位置</th><th>入口空気比 %</th><th>冷却 kg/s</th><th>抽気Tt K</th><th>供給Tt K</th><th>供給Pt kPa</th><th>外部熱 kW</th></tr></thead><tbody>${c.routes.map(r=>`<tr><td>${esc(r.input.name)}</td><td>${r.input.source_stage} → ${r.input.target_stage}</td><td>${esc({before_nozzle:"ノズル前",before_rotor:"ロータ前",after_rotor:"ロータ後",after_diffuser:"ディフューザー後"}[r.input.injection])}</td><td class="num">${fmt(r.input.fraction*100,3)}</td><td class="num">${fmt(r.mass_flow_kg_s,6)}</td><td class="num">${fmt(r.source_total_temperature_k,3)}</td><td class="num">${fmt(r.supply_total_temperature_k,3)}</td><td class="num">${fmt(r.supply_total_pressure_pa/1000,3)}</td><td class="num">${fmt(r.external_heat_w/1000,4)}</td></tr>`).join("")}</tbody></table></div>`)+panel("混合点の圧力・温度・流量",`<div class="table-wrap"><table><thead><tr><th>混合点</th><th>供給Pt kPa</th><th>必要供給圧 kPa</th><th>主流kg/s</th><th>混合後kg/s</th><th>混合前Tt K</th><th>混合後Tt K</th><th>混合後Pt kPa</th><th>エントロピー生成 W/K</th><th>エネルギー残差 J/kg入口空気</th></tr></thead><tbody>${mixes.map(e=>`<tr><td>${esc(e.coolant_name)}</td><td class="num">${fmt(e.coolant_total_pressure_pa/1000,3)}</td><td class="num">${fmt(e.required_supply_pressure_pa/1000,3)}</td><td class="num">${fmt(e.inlet.mass_flow_kg_s,6)}</td><td class="num">${fmt(e.outlet.mass_flow_kg_s,6)}</td><td class="num">${fmt(e.inlet.total_temperature_k,3)}</td><td class="num">${fmt(e.outlet.total_temperature_k,3)}</td><td class="num">${fmt(e.outlet.total_pressure_pa/1000,3)}</td><td class="num">${fmt(e.entropy_generation_w_k,6)}</td><td class="num">${fmt(e.mixing_energy_residual_per_inlet_air_j_kg,9)}</td></tr>`).join("")}</tbody></table></div>`)+panel("圧縮機段ごとの抽気と動力",`<div class="table-wrap"><table><thead><tr><th>段</th><th>通過流量 kg/s</th><th>段出口抽気 kg/s</th><th>抽気後 kg/s</th><th>段動力 kW</th></tr></thead><tbody>${current.result.stage_results.compressor.stages.map(s=>`<tr><td>${s.stage}</td><td class="num">${fmt(s.inlet.mass_flow_kg_s,6)}</td><td class="num">${fmt(s.bleed_fraction*m.air_mass_flow_kg_s,6)}</td><td class="num">${fmt(s.downstream_mass_flow_factor*m.air_mass_flow_kg_s,6)}</td><td class="num">${fmt(s.power_w/1000,4)}</td></tr>`).join("")}</tbody></table></div>`);}

function collect(){const values={};for(const f of config.fields){const text=$("#"+f.key).value;if(!text.trim()||!Number.isFinite(Number(text)))throw new Error(f.label+"を入力してください。");values[f.key]=Number(text)/f.factor;}const h=$("#fuel-h").value;if(!h.trim()||!Number.isFinite(Number(h)))throw new Error("燃料の水素質量割合を入力してください。");return {schema_version:6,cooling:readCooling(),elements:collectElements(),staging:collectStaging(),name:$("#case-name").value.trim(),mode:$("#mode").value,parameters:values,context:structuredClone(context),thermodynamics:{model:$("#thermo-model").value,fuel:$("#fuel").value,fuel_hydrogen_mass_fraction:Number(h)/100}};}
function setInput(inp){$("#case-name").value=inp.name;$("#mode").value=inp.mode;context=structuredClone(inp.context||{});const th=inp.thermodynamics||{model:"constant_cp",fuel:"methane",fuel_hydrogen_mass_fraction:.25};$("#thermo-model").value=th.model;$("#fuel").value=th.fuel;$("#fuel-h").value=th.fuel_hydrogen_mass_fraction*100;for(const f of config.fields)$("#"+f.key).value=Number((inp.parameters[f.key]*f.factor).toPrecision(12));modeFields();thermoFields();setStaging(inp.staging);setElements(inp.elements);setCooling(inp.cooling);generation++;current=null;sweepResult=null;comparison=null;dirty=true;$("#input-error").textContent="";$("#results").innerHTML=empty("条件を読み込みました。「サイクルを計算」を押してください。");renderDetails();sync();}
function markDirty(){generation++;dirty=true;$("#input-error").textContent="";sync();}
function sync(){const ready=current&&!dirty&&!busy;for(const selector of ["#save-case","#export-result","#export-csv","#export-stages","#export-elements","#export-cooling"]){$(selector).disabled=!ready;}$("#export-cooling").disabled=!ready||!current?.result.cooling;$("#calculate").disabled=busy;$("#calculate-top").disabled=busy;$("#stale-banner").hidden=!(dirty&&current);$("#result-status").textContent=busy?"計算しています…":dirty?(current?"入力変更あり · 再計算が必要":"未計算"):`${current?.result.status==="success"?"計算完了":"非発電条件"} · ${current?time(current.completed_at):""}`;$("#export-elements").disabled=!ready||!["compressor","turbine"].some(k=>current?.result.stage_results?.[k]?.elements);if($("#run-sweep"))$("#run-sweep").disabled=!ready;}
async function calculate(event){event?.preventDefault();if(busy)return;let inp;try{inp=collect();}catch(e){$("#input-error").textContent=e.message;return;}const gen=generation;busy=true;sync();try{const result=await api("/api/calculate",{input:inp});if(gen!==generation){notify("計算中に入力が変わりました。再計算してください。");return;}current=result;dirty=false;sweepResult=null;comparison=null;$("#input-error").textContent="";renderResults();renderDetails();}catch(e){dirty=true;$("#input-error").textContent=e.message;notify(e.message,true);}finally{busy=false;sync();}}
function metric(label,value,unit,sub,d=2){return `<div class="metric"><div class="metric-label">${label}</div><div class="metric-value">${fmt(value,d)}<small>${unit}</small></div><div class="metric-sub">${sub}</div></div>`;}
function renderResults(){const r=current.result,m=r.metrics;
  $("#results").innerHTML=`<p class="property-model">計算結果の物性：${thermoLabel(current.input)}${r.thermodynamics?.fuel?" / "+esc(config.fuels[r.thermodynamics.fuel]):""}<br>${esc(elementLabel(current.input))}<br>${esc(coolingLabel(current.input))}${r.cooling?.flow_sizing?" / 逆算後の抽気合計 "+fmt(r.cooling.total_fraction*100,5)+"%":""}</p><div class="metrics">${metric("正味発電出力",m.net_electric_power_w===null?null:m.net_electric_power_w/1000,"kW","発電機出力 − 電気補機")}${metric("正味発電効率",m.electric_efficiency_lhv===null?null:m.electric_efficiency_lhv*100,"%","燃料LHV基準")}${metric("燃料流量",m.fuel_mass_flow_kg_s*3600,"kg/h",fmt(m.fuel_mass_flow_kg_s,5)+" kg/s")}${metric("排気全温",m.exhaust_temperature_k,"K",fmt(m.exhaust_temperature_k-273.15,1)+" °C",1)}</div>`+panel("一軸シンプルサイクル",`<div class="panel-body"><div class="fuel-label">燃料 ${fmt(m.fuel_mass_flow_kg_s*3600,2)} kg/h ↓</div><div class="schematic"><div class="machine"><span>COMPRESSOR</span><strong>圧縮機</strong><span>入力 ${fmt(m.compressor_power_w/1000,1)} kW</span></div><div class="arrow">→</div><div class="machine burner"><span>COMBUSTOR</span><strong>燃焼器</strong><span>${fmt(m.combustor_exit_temperature_k??current.input.parameters.turbine_inlet_temperature_k,0)} K</span></div><div class="arrow">→</div><div class="machine"><span>TURBINE</span><strong>タービン</strong><span>軸へ ${fmt(m.turbine_shaft_power_w/1000,1)} kW</span></div><div class="arrow">→</div><div class="machine"><span>GENERATOR</span><strong>発電機</strong><span>${fmt(m.gross_electric_power_w===null?null:m.gross_electric_power_w/1000,1)} kW</span></div></div><div class="shaft-line">共通軸：タービン軸動力 − 圧縮機動力 − 冷却ポンピング = 取出し軸出力 ${fmt(m.net_shaft_power_w/1000,2)} kW</div><p class="wide-note">ガスは圧縮機→燃焼器→タービン→排気へ流れます。発電機は共通軸の機械負荷です。</p></div>`,`<span class="status-chip ${r.status==="success"?"":"bad"}">${r.status==="success"?"正味発電あり":"非発電条件"}</span>`);
}
function stateChart(){const stations=current.result.stations,W=700,H=230,left=55,right=60,top=25,bottom=45;const maxT=Math.ceil(Math.max(...stations.map(s=>s.total_temperature_k))/200)*200,maxP=Math.ceil(Math.max(...stations.map(s=>s.total_pressure_pa/1000))/100)*100;let svg="";const y=(value,max)=>H-bottom-value/max*(H-top-bottom),x=i=>left+i*(W-left-right)/5;
  for(let i=0;i<=4;i++){const yy=y(maxT*i/4,maxT);svg+=`<line class="grid-line" x1="${left}" y1="${yy}" x2="${W-right}" y2="${yy}"/><text x="${left-9}" y="${yy+4}" text-anchor="end">${fmt(maxT*i/4,0)}</text><text x="${W-right+10}" y="${yy+4}">${fmt(maxP*i/4,0)}</text>`;}
  for(const [key,max,cls] of [["total_temperature_k",maxT,"temperature"],["total_pressure_pa",maxP*1000,"pressure"]]){svg+=`<polyline class="line ${cls}" points="${stations.map((s,i)=>`${x(i)},${y(s[key],max)}`).join(" ")}"/>`;}
  stations.forEach((s,i)=>{svg+=`<text x="${x(i)}" y="${H-18}" text-anchor="middle">${esc(s.id)} ${["大気","圧縮機入口","圧縮機出口","タービン入口","タービン出口","排気"][i]}</text>`;});
  return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="各位置の全温と全圧の推移"><text x="${left}" y="12">全温 K</text><text x="${W-right}" y="12" text-anchor="end">全圧 kPa</text>${svg}</svg><div class="chart-legend"><span><i class="dot orange"></i>全温（左軸）</span><span><i class="dot teal"></i>全圧（右軸）</span></div>`;
}
function energyBars(){const r=current.result,m=r.metrics,b=r.energy_balance;if(r.status!=="success")return '<p class="minor">非発電条件では電気出力の配分図を表示しません。下の動力・収支表を確認してください。</p>';const q=r.cooling?.external_heat_w||0,totalInput=m.fuel_heat_input_w+Math.max(q,0);const parts=[["正味発電",m.net_electric_power_w,"#228a79"],["電気補機",b.auxiliary_power_w,"#8bb9ae"],["発電機損失",b.generator_loss_w,"#b5cbd0"],["機械損失",b.mechanical_loss_w,"#a0b8c0"],["燃焼損失",b.combustion_loss_w,"#c5a67c"],["排気の正味顕熱",b.exhaust_net_sensible_energy_w,"#d7bf9f"]];if(q<0)parts.push(["冷却流路の外部放熱",-q,"#79a9bb"]);return parts.map(([label,value,color])=>`<div class="bar-row"><span>${label}</span><div class="bar-track"><svg viewBox="0 0 100 12" preserveAspectRatio="none"><rect width="${Math.max(0,Math.min(100,value/totalInput*100))}" height="12" fill="${color}"/></svg></div><span class="bar-number">${fmt(value/1000,2)} kW</span></div>`).join("")+`<p class="minor">総入熱 ${fmt(totalInput/1000,2)} kW（燃料＋流路外部加熱）に対する配分。排気の正味顕熱は、流入空気の顕熱を差し引いた値です。</p>`;}
function powerRows(){const m=current.result.metrics,b=current.result.energy_balance;return [["空気流量",m.air_mass_flow_kg_s,"kg/s"],["燃焼ガス流量（空気＋燃料）",m.gas_mass_flow_kg_s,"kg/s"],["燃空比（入口空気基準）",m.fuel_air_ratio,"kg-fuel/kg-air"],["燃空比（燃焼器空気基準）",m.combustor_fuel_air_ratio??m.fuel_air_ratio,"kg-fuel/kg-air"],["圧縮機端点効率（抽気時は動力比と別）",m.compressor_effective_efficiency*100,"%"],["タービン全体ηtt（冷却時は未定義）",pct(m.turbine_effective_efficiency),"%"],["冷却タービン熱力学効率",pct(m.turbine_thermodynamic_efficiency),"%"],["冷却ポンピング軸動力",(m.cooling_pumping_power_w??0)/1000,"kW"],["翼から冷却空気への内部伝熱",(m.blade_heat_transfer_w??0)/1000,"kW"],["圧縮機動力",m.compressor_power_w/1000,"kW"],["タービンガス仕事率",m.turbine_gas_power_w/1000,"kW"],["取出し軸出力",m.net_shaft_power_w/1000,"kW"],["燃料投入熱（LHV）",m.fuel_heat_input_w/1000,"kW"],["軸熱効率（LHV）",m.shaft_efficiency_lhv===null?null:m.shaft_efficiency_lhv*100,"%"],["熱消費率（正味発電・LHV）",m.heat_rate_kj_kwh,"kJ/kWh"],["燃料消費率（正味発電）",m.specific_fuel_consumption_kg_kwh,"kg/kWh"],["タービン膨張比（入口/出口）",m.turbine_expansion_ratio,"—"],["圧縮機動力/タービン軸動力",m.back_work_ratio*100,"%"],["入口空気 / TITガスの比熱比",null,`${fmt(m.gamma_air,5)} / ${fmt(m.gamma_gas,5)}`],["エネルギー収支残差（軸基準）",b.shaft_balance_residual_w,"W"],["エネルギー収支残差（発電基準）",b.electric_balance_residual_w,"W"],["質量収支残差",b.mass_balance_residual_kg_s,"kg/s"]];}
function renderDetails(){if(tab==="cases"){renderCases();return;}if(tab==="model"){renderModel();return;}if(!current){$("#details").innerHTML=empty("計算すると詳細結果を表示します。");return;}if(tab==="cooling"){renderCooling();return;}if(tab==="elements"){renderElements();return;}if(tab==="stages"){renderStages();return;}if(tab==="properties"){renderProperties();return;}if(tab==="sweep"){renderSweep();return;}const r=current.result;
  $("#details").innerHTML=panel("状態表",`<div class="table-wrap"><table><thead><tr><th>位置</th><th>全温 K</th><th>全圧 kPa・絶対圧</th><th>質量流量 kg/s</th></tr></thead><tbody>${r.stations.map(s=>`<tr><td><span class="state-number">${s.id}</span>${esc(s.name)}</td><td class="num">${fmt(s.total_temperature_k,2)}</td><td class="num">${fmt(s.total_pressure_pa/1000,3)}</td><td class="num">${fmt(s.mass_flow_kg_s,5)}</td></tr>`).join("")}</tbody></table></div><div class="panel-body"><p class="minor">位置0は静止大気。位置5は流速を無視した排気境界です。吸排気ダクトは断熱、全温一定として扱います。</p></div>`)+panel("温度・圧力の推移",`<div class="panel-body">${stateChart()}</div>`)+`<div class="grid-two">${panel("燃料投入熱の配分",`<div class="panel-body">${energyBars()}</div>`)}${panel("モデルの注意事項",`<div class="panel-body">${r.warnings.map(w=>`<div class="warning">${esc(w)}</div>`).join("")}</div>`)}</div>`+panel("動力・性能・収支",`<div class="table-wrap"><table><tbody>${powerRows().map(([label,value,unit])=>`<tr><td>${label}</td><td class="num">${fmt(value,["W","kg/s"].includes(unit)?6:4)}</td><td>${esc(unit)}</td></tr>`).join("")}</tbody></table></div>`);
}
function renderSweep(){const previous=sweepResult;$("#details").innerHTML=`<div class="notice">基準計算の空気流量を固定し、圧力比だけを変える設計点感度解析です。目標出力モードでも、スイープ中に流量を再調整しません。性能マップを使うオフデザイン解析は含みません。</div>`+panel("圧力比スイープ",`<div class="panel-body"><div class="sweep-form"><label>圧力比の下限<input type="number" id="sweep-min" min="1.01" max="50" step="any" value="1.2"></label><label>上限<input type="number" id="sweep-max" min="1.01" max="50" step="any" value="20"></label><label>点数<input type="number" id="sweep-count" min="3" max="101" step="1" value="31"></label><button class="button primary" id="run-sweep">感度を計算</button></div><div id="sweep-output"></div></div>`);if(previous)drawSweep();sync();}
function drawSweep(){const s=sweepResult,pts=s.points,valid=pts.filter(p=>p.net_electric_power_w!==null),W=700,H=260,L=60,R=30,T=25,B=45;const max=Math.max(1,...valid.map(p=>p.net_electric_power_w/1000)),min=Math.min(0,...valid.map(p=>p.net_electric_power_w/1000));const x=v=>L+(v-pts[0].pressure_ratio)/(pts[pts.length-1].pressure_ratio-pts[0].pressure_ratio)*(W-L-R),y=v=>T+(max-v)/(max-min)*(H-T-B);let svg="";for(let i=0;i<=4;i++){const v=min+(max-min)*i/4;svg+=`<line class="grid-line" x1="${L}" y1="${y(v)}" x2="${W-R}" y2="${y(v)}"/><text x="${L-8}" y="${y(v)+4}" text-anchor="end">${fmt(v,1)}</text>`;}let segment=[];const flush=()=>{if(segment.length)svg+=`<polyline class="line pressure" points="${segment.join(" ")}"/>`;segment=[];};pts.forEach(p=>{if(p.net_electric_power_w===null)flush();else segment.push(`${x(p.pressure_ratio)},${y(p.net_electric_power_w/1000)}`);});flush();for(let i=0;i<5;i++){const v=pts[0].pressure_ratio+(pts[pts.length-1].pressure_ratio-pts[0].pressure_ratio)*i/4;svg+=`<text x="${x(v)}" y="${H-15}" text-anchor="middle">${fmt(v,2)}</text>`;}const best=valid.filter(p=>p.net_electric_power_w>0).sort((a,b)=>b.net_electric_power_w-a.net_electric_power_w)[0];$("#sweep-output").innerHTML=`<p class="minor">固定空気流量 ${fmt(s.fixed_air_mass_flow_kg_s,5)} kg/s · 正味発電出力 kW / 圧力比</p><svg viewBox="0 0 ${W} ${H}" class="chart" role="img" aria-label="圧力比と正味発電出力の感度解析">${svg}</svg><p class="minor">${best?`走査点での最大出力：圧力比 ${fmt(best.pressure_ratio,3)}、${fmt(best.net_electric_power_w/1000,2)} kW。連続最適値や実機の運転点ではありません。`:"正味発電出力が正となる走査点はありません。"}</p><div class="table-wrap"><table><thead><tr><th>圧力比</th><th>正味発電 kW</th><th>効率 %</th><th>状態・理由</th></tr></thead><tbody>${pts.map(p=>`<tr><td class="num">${fmt(p.pressure_ratio,3)}</td><td class="num">${fmt(p.net_electric_power_w===null?null:p.net_electric_power_w/1000,2)}</td><td class="num">${fmt(p.electric_efficiency_lhv===null?null:p.electric_efficiency_lhv*100,2)}</td><td>${p.status==="success"?"計算完了":esc(p.reason||"非発電条件")}</td></tr>`).join("")}</tbody></table></div>`;}
async function refreshCases(){caseList=await api("/api/cases");}
function renderCases(){$("#details").innerHTML=`<div class="notice">保存した計算ケースは入力と結果のスナップショットです。後から入力を変えても上書きされません。通常データはこのアプリ専用のDBに保存します。</div>`+panel("保存ケース",caseList.length?`<div class="table-wrap"><table><thead><tr><th>ケース / 保存日時</th><th>正味発電</th><th>操作</th></tr></thead><tbody>${caseList.map(c=>`<tr><td><div class="case-title">${esc(c.name)}</div><div class="minor">${time(c.created_at)}</div></td><td class="num">${fmt(c.net_power_w===null?null:c.net_power_w/1000,2)} kW</td><td><button class="text-button" data-load="${c.id}">入力・結果を開く</button></td></tr>`).join("")}</tbody></table></div>`:empty("「ケースを保存」で、現在の計算を保存できます。"))+panel("現在の計算と比較",`<div class="panel-body"><label class="minor" for="compare-case">比較する保存ケース</label><select class="case-select" id="compare-case"><option value="">保存ケースを選択してください</option>${caseList.map(c=>`<option value="${c.id}">${esc(c.name)} / ${time(c.created_at)}</option>`).join("")}</select><div id="compare-output"></div></div>`);if(comparison&&caseList.some(c=>c.id===comparison.run_id)){$("#compare-case").value=comparison.run_id;drawComparison();}}

function elementComparison(a,b){const rows=[];const add=(label,x,y)=>{if(x!==y)rows.push([label,x,y]);};for(const key of ["compressor","turbine"]){const label=key==="compressor"?"圧縮機":"タービン",x=a.elements?.[key],y=b.elements?.[key];add(label+" 要素モード",x?.enabled?"使用":"未使用",y?.enabled?"使用":"未使用");if(!x?.enabled&&!y?.enabled)continue;add(label+" 入口流速 m/s",x?.inlet_velocity_m_s,y?.inlet_velocity_m_s);const n=Math.max(x?.stages.length||0,y?.stages.length||0);for(let i=0;i<n;i++){const p=label+(i+1)+"段 ",u=x?.stages[i],v=y?.stages[i];add(p+"ロータ効率 %",u?.rotor_efficiency*100,v?.rotor_efficiency*100);add(p+"ロータ出口流速 m/s",u?.rotor_exit_velocity_m_s,v?.rotor_exit_velocity_m_s);for(const [role,name] of key==="compressor"?[["diffuser","ディフューザー"],["return_channel","リターンチャネル"]]:[["nozzle","ノズル"],["diffuser","出口ディフューザー"]]){const z=u?.[role],w=v?.[role];add(p+name+" 使用",z?.enabled?"使用":"未使用",w?.enabled?"使用":"未使用");add(p+name+" モデル",z?.model==="cp"?"Cp":z?.model==="loss"?"ζ":"なし",w?.model==="cp"?"Cp":w?.model==="loss"?"ζ":"なし");add(p+name+" 係数",z?.coefficient,w?.coefficient);add(p+name+" 出口流速 m/s",z?.exit_velocity_m_s,w?.exit_velocity_m_s);}}}const value=x=>typeof x==="number"?(Number.isFinite(x)?fmt(x,5):"—"):esc(x??"—");return panel("要素条件の差分",rows.length?`<div class="table-wrap"><table><thead><tr><th>条件</th><th>現在</th><th>保存</th></tr></thead><tbody>${rows.map(([label,x,y])=>`<tr class="changed"><td>${esc(label)}</td><td>${value(x)}</td><td>${value(y)}</td></tr>`).join("")}</tbody></table></div>`:empty("要素条件の変更はありません。"));}


function coolingComparison(a,b){const x=a.cooling,y=b.cooling;if(!x?.enabled&&!y?.enabled)return "";const rows=[];const add=(name,u,v)=>{if(u!==v)rows.push([name,u,v]);};add("冷却使用",x?.enabled?"使用":"未使用",y?.enabled?"使用":"未使用");add("温度基準",x?.temperature_basis,y?.temperature_basis);add("燃焼器上限 K",x?.combustor_exit_limit_k,y?.combustor_exit_limit_k);for(let i=0;i<Math.max(x?.circuits.length||0,y?.circuits.length||0);i++){const u=x?.circuits[i],v=y?.circuits[i],p="冷却流路"+(i+1)+" ";for(const [key,label] of [["name","名称"],["source_stage","抽気段"],["fraction","入口空気基準割合"],["target_stage","注入段"],["injection","混合位置"],["pressure_loss_fraction","流路圧損率"],["heat_j_kg","外部熱 J/kg"],["mix_pressure_loss_fraction","混合圧損率"],["required_pressure_margin","必要圧力余裕"],["mixed_velocity_m_s","混合後流速 m/s"]])add(p+label,u?.[key],v?.[key]);}const value=v=>typeof v==="number"?(Number.isFinite(v)?fmt(v,6):"—"):esc(v??"—");return panel("冷却条件の差分",rows.length?`<div class="table-wrap"><table><thead><tr><th>条件</th><th>現在</th><th>保存</th></tr></thead><tbody>${rows.map(([name,u,v])=>`<tr class="changed"><td>${esc(name)}</td><td>${value(u)}</td><td>${value(v)}</td></tr>`).join("")}</tbody></table></div>`:empty("冷却条件の変更はありません。"));}

function drawComparison(){if(!current){$("#compare-output").innerHTML=empty("先に現在の条件を計算してください。");return;}const rows=[];for(const f of config.fields){const a=current.input.parameters[f.key],b=comparison.input.parameters[f.key];rows.push([f.label,a*f.factor,b*f.factor,f.unit,a!==b]);}for(const [key,label,factor,unit] of [["net_electric_power_w","正味発電出力",.001,"kW"],["net_shaft_power_w","取出し軸出力",.001,"kW"],["electric_efficiency_lhv","正味発電効率",100,"%"],["air_mass_flow_kg_s","計算後の空気流量",1,"kg/s"],["fuel_mass_flow_kg_s","燃料流量",3600,"kg/h"],["exhaust_temperature_k","排気全温",1,"K"]]){const a=current.result.metrics[key],b=comparison.result.metrics[key];rows.push([label,a===null?null:a*factor,b===null?null:b*factor,unit,a!==b]);}$("#compare-output").innerHTML=`<p class="minor">現在：${esc(current.input.name)} / ${thermoLabel(current.input)}（${current.input.mode==="airflow"?"流量指定":"出力指定"}） / 保存：${esc(comparison.input.name)} / ${thermoLabel(comparison.input)}（${comparison.input.mode==="airflow"?"流量指定":"出力指定"}）${dirty?" · 現在の入力は未再計算です。表示は前回結果の比較です。":""}</p><p class="minor">現在の段構成：${esc(stagingLabel(current.input))}<br>${esc(elementLabel(current.input))}<br>保存の段構成：${esc(stagingLabel(comparison.input))}<br>${esc(elementLabel(comparison.input))}<br>現在：${esc(coolingLabel(current.input))}<br>保存：${esc(coolingLabel(comparison.input))}</p>${elementComparison(current.input,comparison.input)}${coolingComparison(current.input,comparison.input)}${bladeComparison(current.input,comparison.input)}<div class="table-wrap"><table><thead><tr><th>条件・結果</th><th>現在の計算</th><th>保存ケース</th><th>単位</th></tr></thead><tbody>${rows.map(([label,a,b,unit,changed])=>`<tr class="${changed?"changed":""}"><td>${label}</td><td class="num">${fmt(a,4)}</td><td class="num">${fmt(b,4)}</td><td>${esc(unit)}</td></tr>`).join("")}</tbody></table></div>`;}
function renderProperties(){const r=current.result,th=r.thermodynamics||{},data=th.dataset;$("#details").innerHTML=`<div class="notice">表示中の計算：${thermoLabel(current.input)}。顕熱h・エントロピー温度関数は298.15 K基準です。各要素内は組成固定、冷却混合点では組成と流量を更新します。</div>`+panel("位置ごとの温度依存物性",`<div class="table-wrap"><table><thead><tr><th>位置</th><th>T K</th><th>cp kJ/(kg·K)</th><th>cv kJ/(kg·K)</th><th>比熱比 γ</th><th>R J/(kg·K)</th><th>顕熱h kJ/kg</th><th>エントロピー温度関数 J/(kg·K)</th></tr></thead><tbody>${r.stations.map(s=>`<tr><td>${esc(s.id)} ${esc(s.name)}</td><td class="num">${fmt(s.total_temperature_k,2)}</td><td class="num">${fmt(s.cp_j_kg_k===undefined?null:s.cp_j_kg_k/1000,5)}</td><td class="num">${fmt(s.cv_j_kg_k===undefined?null:s.cv_j_kg_k/1000,5)}</td><td class="num">${fmt(s.gamma,6)}</td><td class="num">${fmt(s.gas_constant_j_kg_k,5)}</td><td class="num">${fmt(s.sensible_enthalpy_j_kg===undefined?null:s.sensible_enthalpy_j_kg/1000,3)}</td><td class="num">${fmt(s.entropy_thermal_function_j_kg_k,4)}</td></tr>`).join("")}</tbody></table></div>`)+(data?panel("NASAデータと燃焼ガスの組成",`<div class="panel-body"><dl class="definition-list"><dt>データ</dt><dd>${esc(data.dataset_id)}</dd><dt>NASA版</dt><dd><code>${esc(data.source_commit)}</code></dd><dt>適用範囲</dt><dd>200〜6000 K（外挿しません）</dd><dt>燃料</dt><dd>${esc(config.fuels[th.fuel])}</dd><dt>燃料のC/H</dt><dd>${fmt(th.fuel_element_mass_fractions.C*100,4)} / ${fmt(th.fuel_element_mass_fractions.H*100,4)} 質量%</dd><dt>当量比</dt><dd>${fmt(th.equivalence_ratio,6)}</dd></dl><div class="table-wrap"><table><thead><tr><th>化学種</th><th>乾燥空気 質量%</th><th>燃焼後 質量%</th></tr></thead><tbody>${["N2","O2","Ar","CO2","H2O"].map(k=>`<tr><td>${k}</td><td class="num">${fmt((th.air_mass_fractions[k]||0)*100,6)}</td><td class="num">${fmt((th.product_mass_fractions[k]||0)*100,6)}</td></tr>`).join("")}</tbody></table></div><p class="minor">NASA公式CEAデータを使用しますが、GasTurbの独自補間表・燃焼平衡計算そのものではありません。乾燥空気の仮定、燃料組成、LHVも合わせない限り比較できません。</p></div>`):'<div class="notice">比熱一定モデルでは燃焼組成を計算せず、入力したcp・Rを使います。</div>');}
function renderModel(){const c=current,d=config?.thermo_dataset;$("#details").innerHTML=panel("モデルと対象範囲",`<div class="panel-body"><div class="notice">定常・一軸・開放シンプルサイクル。NASA9温度依存モデルと比熱一定の旧モデルを選択できます。</div><p class="minor">NASAモデルではcp(T)・h(T)・エントロピー関数を使い、等エントロピー温度と効率補正後の温度を数値的に解きます。比熱比だけを一定指数に代入する近似は使用しません。燃焼は乾燥空気とC/H燃料の希薄完全燃焼、N2/O2/Ar/CO2/H2Oの凍結組成です。冷却設定では圧縮機段出口の抽気とタービン要素間の混合を扱います。燃焼の化学平衡・解離、湿度、冷却孔の流れ・3D温度分布・回転流路の詳細解析は未対応です。</p><p class="minor">燃料は298.15 K、LHVは独立入力です。顕熱の基準を揃え、生成エンタルピーをLHVに重ねて加えません。機械・発電機効率の定義は旧版と同じです。回転数は冷却ポンピングと任意の段平均径からの周速・負荷係数に使用します。</p><p class="minor">NASAデータ ${esc(d?.dataset_id)}。GasTurbがNASA CEA由来データを使用することは公式資料で確認しましたが、同一版の表・補間・燃焼モデルや数値一致は未確認です。</p><a class="button" href="/guide" target="_blank" rel="noopener">計算式・出典・使い方を見る</a></div>`)+panel("将来の統合に使う記録",`<div class="panel-body"><dl class="definition-list"><dt>モジュール</dt><dd>${esc(config?.module_id)} / ${esc(config?.module_version)}（schema 6）</dd><dt>計算ID</dt><dd>${esc(c?.run_id||"未計算")}</dd><dt>入力ハッシュ</dt><dd><code>${esc(c?.input_hash||"未計算")}</code></dd><dt>案件ID</dt><dd>${esc(context.project_id||"単独利用（未指定）")}</dd><dt>部品ID</dt><dd>${esc(context.component_id||"未指定")}</dd><dt>入力元の版</dt><dd>${esc(context.source_revision??"未指定")}</dd></dl><p class="minor">入力と結果JSONに物性モデル・燃料組成・NASAデータ版・段構成を記録します。全体モードは一定ポリトロープ効率の経路上の段配分です。要素モードはインペラー/ロータ効率・Cp/ζ・流速から全体効率と動力を計算します。schema 1は比熱一定、schema 2は元の物性モデルを維持して各1段へ移行し、schema 3は段構成を維持して要素モードなしへ移行し、schema 4は要素条件を維持して冷却なしへ移行し、schema 5は従来の冷却条件を維持して翼熱・ポンピングなしへ移行します。旧結果は再計算を要求します。管理アプリのDBは変更しません。</p></div>`);}
function confirmReplace(){if(!dirty)return Promise.resolve(true);return new Promise(resolve=>{const d=$("#confirmation");const finish=value=>{d.close();d.oncancel=null;resolve(value);};$("#confirm-no").onclick=()=>finish(false);$("#confirm-yes").onclick=()=>finish(true);d.oncancel=e=>{e.preventDefault();finish(false);};d.showModal();$("#confirm-no").focus();});}
$("#inputs").addEventListener("submit",calculate);$("#inputs").addEventListener("input",markDirty);$("#mode").addEventListener("change",()=>{modeFields();markDirty();});
for(const selector of ["#thermo-model","#fuel"]){$(selector).addEventListener("change",()=>{thermoFields();markDirty();});}$("#fuel-h").addEventListener("input",markDirty);
$("#reset-sample").onclick=async()=>{if(await confirmReplace()){setInput(config.default);notify("サンプル入力に戻しました。再計算してください。");}};
$("#export-input").onclick=()=>{try{download("cycle-input.json",JSON.stringify(collect(),null,2));}catch(e){notify(e.message,true);}};
$("#export-result").onclick=()=>{if(current&&!dirty&&!busy)download("cycle-result.json",JSON.stringify(current,null,2));};
$("#export-csv").onclick=()=>{if(!current||dirty||busy)return;const rows=[["station_id","station_name","total_temperature_K","total_pressure_Pa_absolute","mass_flow_kg_s","fluid","cp_J_kg_K","cv_J_kg_K","gamma","R_J_kg_K","sensible_h_J_kg","entropy_thermal_J_kg_K"],...current.result.stations.map(s=>[s.id,s.name,s.total_temperature_k,s.total_pressure_pa,s.mass_flow_kg_s,s.fluid,s.cp_j_kg_k,s.cv_j_kg_k,s.gamma,s.gas_constant_j_kg_k,s.sensible_enthalpy_j_kg,s.entropy_thermal_function_j_kg_k])];const csv=rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(",")).join("\r\n");download("cycle-stations.csv","\ufeff"+csv,"text/csv;charset=utf-8");};
$("#import-input").onclick=()=>$("#file-input").click();$("#file-input").onchange=async event=>{const file=event.target.files[0];event.target.value="";if(!file)return;try{if(file.size>1_000_000)throw new Error("JSONは1MB以内にしてください。");const imported=await api("/api/import",{document:JSON.parse(await file.text())});if(await confirmReplace()){setInput(imported.input);notify(imported.note);}}catch(e){notify(e.message,true);}};
$("#save-case").onclick=async()=>{if(!current||dirty||busy)return;const version=generation,inp=structuredClone(current.input);busy=true;sync();try{const saved=await api("/api/save",{input:inp});await refreshCases();if(version===generation){current=saved;renderResults();renderDetails();}notify("計算ケースを保存しました。");}catch(e){notify(e.message,true);}finally{busy=false;sync();}};
document.addEventListener("click",async event=>{try{const t=event.target.closest("[data-tab]");if(t){tab=t.dataset.tab;document.querySelectorAll(".tab").forEach(x=>{const active=x.dataset.tab===tab;x.classList.toggle("active",active);x.setAttribute("aria-selected",String(active));});if(tab==="cases")await refreshCases();renderDetails();return;}const load=event.target.closest("[data-load]");if(load){const saved=await api("/api/case?id="+load.dataset.load);if(await confirmReplace()){if(saved.module_version!==config.module_version){const migrated=await api("/api/import",{document:saved});setInput(migrated.input);notify("旧版ケースの入力を移行しました。結果は再計算してください。");}else{setInput(saved.input);current=saved;dirty=false;renderResults();renderDetails();sync();notify("保存時の入力・結果を開きました。");}}return;}if(event.target.id==="run-sweep"){if(!current||dirty||busy)return;const gen=generation,minimum=Number($("#sweep-min").value),maximum=Number($("#sweep-max").value),count=Number($("#sweep-count").value);busy=true;sync();try{const response=await api("/api/sweep",{input:current.input,minimum,maximum,count});if(gen===generation){sweepResult=response;if(tab==="sweep")drawSweep();}}finally{busy=false;sync();}}}catch(e){notify(e.message,true);}});
document.addEventListener("change",async event=>{if(event.target.id!=="compare-case")return;const caseId=event.target.value;if(!caseId){comparison=null;$("#compare-output").innerHTML="";return;}try{const saved=await api("/api/case?id="+caseId);if(tab==="cases"&&$("#compare-case")?.value===caseId){comparison=saved;drawComparison();}}catch(e){notify(e.message,true);}});
(async()=>{try{config=await api("/api/schema");$("#fuel").innerHTML=Object.entries(config.fuels).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join("");await refreshCases();initializeFields();setInput(config.default);await calculate();}catch(e){$("#input-error").textContent=e.message;notify(e.message,true);}})();

$("#staging-controls").addEventListener("input",markDirty);
$("#staging-controls").addEventListener("change",markDirty);
$("#stage-sample").onclick=()=>{setStaging({compressor:{count:4,distribution:"pressure",weights:[1,1,1,1],mean_diameters_m:[.12,.12,.12,.12]},turbine:{count:3,distribution:"work",weights:[4,3.5,2.5],mean_diameters_m:[.14,.14,.14]}});setElements(config.default.elements);setCooling(config.default.cooling);markDirty();notify("要素モードを解除しました。操作説明用の段配分例です。運転条件は維持します。再計算してください。");};
$("#export-stages").onclick=()=>{if(!current||dirty||busy)return;const rows=[["component","stage","inlet_T_K","outlet_T_K","inlet_P_Pa","outlet_P_Pa","mass_flow_kg_s","pressure_ratio","specific_work_J_kg","power_W","transmitted_power_W","stage_eta_tt","equivalent_eta_p","overall_eta_tt","work_fraction","log_pressure_fraction","entropy_generation_J_kg_K","mean_diameter_m","blade_speed_m_s","psi_dh_over_U2","outlet_cp_J_kg_K","outlet_gamma","outlet_mass_flow_kg_s","turbine_thermodynamic_efficiency","entropy_generation_W_K"]];for(const [key,x] of Object.entries(current.result.stage_results)){for(const s of x.stages)rows.push([key,s.stage,s.inlet.total_temperature_k,s.outlet.total_temperature_k,s.inlet.total_pressure_pa,s.outlet.total_pressure_pa,s.inlet.mass_flow_kg_s,s.pressure_ratio,s.specific_work_j_kg,s.power_w,s.transmitted_power_w,s.isentropic_efficiency,x.polytropic_efficiency,x.recovered_overall_isentropic_efficiency,s.work_fraction,s.pressure_log_fraction,s.entropy_generation_j_kg_k,s.mean_diameter_m,s.blade_speed_m_s,s.loading_coefficient,s.outlet.cp_j_kg_k,s.outlet.gamma,s.outlet.mass_flow_kg_s,x.thermodynamic_efficiency,s.entropy_generation_w_k]);}download("cycle-stages.csv","\ufeff"+rows.map(r=>r.map(v=>'"'+String(v??"").replaceAll('"','""')+'"').join(",")).join("\r\n"),"text/csv;charset=utf-8");};

$("#element-controls").addEventListener("input",markDirty);
$("#element-controls").addEventListener("change",event=>{try{if(event.target.id.endsWith("-enabled")){const key=event.target.id.includes("compressor")?"compressor":"turbine";if(event.target.checked&&$("#"+key+"-distribution").value!=="pressure"){$("#"+key+"-distribution").value="pressure";$("#"+key+"-weights").value="";notify("要素モードの段配分を対数圧力比の均等配分へ変更しました。");}resizeElementStages();}elementFields();markDirty();}catch(e){notify(e.message,true);}});
for(const key of ["compressor","turbine"]){$("#"+key+"-count").addEventListener("change",()=>{try{resizeElementStages();markDirty();}catch(e){notify(e.message,true);}});}
$("#element-sample").onclick=()=>{setStaging({compressor:{count:2,distribution:"pressure",weights:[1,1],mean_diameters_m:[.12,.12]},turbine:{count:2,distribution:"pressure",weights:[1,1],mean_diameters_m:[.14,.14]}});const value=structuredClone(config.default.elements);for(const key of ["compressor","turbine"]){value[key].enabled=true;value[key].stages=[structuredClone(config.element_stage_templates[key]),structuredClone(config.element_stage_templates[key])];}setElements(value);setCooling(config.default.cooling);markDirty();notify("操作説明用の2段要素例を設定しました。運転条件は維持します。再計算してください。");};
$("#export-elements").onclick=()=>{if(!current||dirty||busy)return;const rows=[["machine","stage","element","inlet_Tt_K","outlet_Tt_K","inlet_Pt_Pa","outlet_Pt_Pa","inlet_T_K","outlet_T_K","inlet_p_Pa","outlet_p_Pa","inlet_V_m_s","outlet_V_m_s","outlet_Mach","inlet_q_Pa","model","coefficient","Cp","zeta","Pt_loss_Pa","rotor_eta_tt","rotor_PR","specific_work_J_kg","power_W","mass_flow_kg_s","outlet_effective_area_m2","entropy_generation_J_kg_K"]];for(const [key,x] of Object.entries(current.result.stage_results)){for(const e of x.elements||[])rows.push([key,e.stage,e.name,e.inlet.total_temperature_k,e.outlet.total_temperature_k,e.inlet.total_pressure_pa,e.outlet.total_pressure_pa,e.inlet.static_temperature_k,e.outlet.static_temperature_k,e.inlet.static_pressure_pa,e.outlet.static_pressure_pa,e.inlet.velocity_m_s,e.outlet.velocity_m_s,e.outlet.mach,e.inlet.dynamic_pressure_pa,e.coefficient_model,e.specified_coefficient,e.pressure_recovery_coefficient,e.total_pressure_loss_coefficient,e.total_pressure_loss_pa,e.rotor_isentropic_efficiency,e.rotor_pressure_ratio,e.specific_work_j_kg,e.power_w,e.outlet.mass_flow_kg_s,e.outlet.effective_flow_area_m2,e.entropy_generation_j_kg_k]);}download("cycle-elements.csv","\ufeff"+rows.map(r=>r.map(v=>'"'+String(v??"").replaceAll('"','""')+'"').join(",")).join("\r\n"),"text/csv;charset=utf-8");};

$("#cooling-controls").addEventListener("input",markDirty);
$("#cooling-controls").addEventListener("change",event=>{try{if(event.target.id==="cooling-enabled"&&event.target.checked){if(!$("#element-turbine-enabled").checked){$("#element-turbine-enabled").checked=true;$("#turbine-distribution").value="pressure";$("#turbine-weights").value="";resizeElementStages();notify("冷却用にタービン要素モードと対数圧力配分を有効にしました。ロータ効率を確認してください。");}}coolingFields();markDirty();}catch(e){notify(e.message,true);}});
$("#cooling-add").onclick=()=>{try{coolingDraft=readCooling();if(coolingDraft.circuits.length>=12)throw new Error("冷却流路は12本以内です。");const c=structuredClone(config.cooling_circuit_template);c.source_stage=Number($("#compressor-count").value);c.name="冷却空気"+(coolingDraft.circuits.length+1);coolingDraft.circuits.push(c);renderCoolingInputs();markDirty();}catch(e){notify(e.message,true);}};
$("#cooling-controls").addEventListener("click",event=>{const button=event.target.closest("[data-remove-cooling]");if(!button)return;try{coolingDraft=readCooling();coolingDraft.circuits.splice(Number(button.dataset.removeCooling),1);renderCoolingInputs();markDirty();}catch(e){notify(e.message,true);}});
$("#cooling-sample").onclick=()=>{$("#element-sample").click();const a=structuredClone(config.cooling_circuit_template),b=structuredClone(a);Object.assign(a,{name:"1段ノズル前冷却",source_stage:2,target_stage:1,injection:"before_nozzle",fraction:.04,mixed_velocity_m_s:60});Object.assign(b,{name:"2段ロータ前冷却",source_stage:1,target_stage:2,injection:"before_rotor",fraction:.03,mixed_velocity_m_s:180});setCooling({enabled:true,temperature_basis:"combustor_exit",combustor_exit_limit_k:2400,circuits:[a,b]});markDirty();notify("操作説明用の2段・2流路冷却例です。運転条件は維持します。NASA物性を使用してください。");};
$("#export-cooling").onclick=()=>{if(!current||dirty||busy||!current.result.cooling)return;const c=current.result.cooling,mixes=current.result.stage_results.turbine.elements.filter(e=>e.kind==="mixing");const rows=[["name","source_stage","target_stage","injection","fraction_of_inlet_air","coolant_kg_s","source_Tt_K","source_Pt_Pa","supply_Tt_K","supply_Pt_Pa","required_supply_Pa","external_heat_W","primary_kg_s","mixed_kg_s","primary_Tt_K","mixed_Tt_K","mixed_Pt_Pa","entropy_generation_W_K","mixing_energy_residual_J_kg_inlet_air","pumping_W","coolant_after_blade_K","gas_after_blade_K","blade_heat_W","metal_max_K","metal_margin_K"]];for(const r of c.routes){const e=mixes.find(x=>x.route_index===r.index);rows.push([r.input.name,r.input.source_stage,r.input.target_stage,r.input.injection,r.input.fraction,r.mass_flow_kg_s,r.source_total_temperature_k,r.source_total_pressure_pa,r.supply_total_temperature_k,r.supply_total_pressure_pa,e.required_supply_pressure_pa,r.external_heat_w,e.inlet.mass_flow_kg_s,e.outlet.mass_flow_kg_s,e.inlet.total_temperature_k,e.outlet.total_temperature_k,e.outlet.total_pressure_pa,e.entropy_generation_w_k,e.mixing_energy_residual_per_inlet_air_j_kg,r.pumping_power_w,r.thermal?.coolant_outlet_temperature_k,r.thermal?.gas_outlet_temperature_k,r.thermal?.heat_w,r.thermal?.metal_max_temperature_k,r.thermal?.metal_margin_k]);}download("cycle-cooling.csv","\ufeff"+rows.map(r=>r.map(v=>'"'+String(v??"").replaceAll('"','""')+'"').join(",")).join("\r\n"),"text/csv;charset=utf-8");};


const bladeLabels={
 thermal:{gas_h_w_m2_k:["ガス側熱伝達率","W/(m² K)"],coolant_h_w_m2_k:["冷却側熱伝達率","W/(m² K)"],gas_area_m2:["ガス側伝熱面積","m²・全翼合計"],coolant_area_m2:["冷却側伝熱面積","m²・全翼合計"],metal_thickness_m:["翼金属厚さ","m"],metal_conductivity_w_m_k:["金属熱伝導率","W/(m K)"],tbc_thickness_m:["TBC厚さ","m"],tbc_conductivity_w_m_k:["TBC熱伝導率","W/(m K)"],film_effectiveness:["断熱フィルム冷却有効度","0〜0.95"],metal_limit_k:["許容翼金属温度","K"],min_fraction:["逆算抽気率の下限","割合・入口空気基準"],max_fraction:["逆算抽気率の上限","割合・入口空気基準"]},
 pumping:{inlet_radius_m:["ポンプ入口半径","m"],outlet_radius_m:["ポンプ出口半径","m"],inlet_swirl_ratio:["入口旋回比 Cθ/U","0〜1"],outlet_swirl_ratio:["出口旋回比 Cθ/U","0〜1"],isentropic_efficiency:["ポンピング全圧効率","0.1〜1"]}};
function bladeInputs(c,i){return ["thermal","pumping"].map(group=>{const v=c[group]||config.cooling_circuit_template[group],label=group==="thermal"?"翼熱モデル":"ロータ冷却ポンピング",p=`b-${i}-${group}-`;return `<details class="blade-input"><summary>${label}</summary><div class="stage-input-body"><label><input type="checkbox" id="${p}enabled" aria-label="冷却流路${i+1} ${label}を使用" ${v.enabled?"checked":""}> ${label}を使用</label>${group==="thermal"?`<label class="field">計算モード<select id="${p}mode" aria-label="冷却流路${i+1} 翼熱計算モード"><option value="fixed_flow" ${v.mode==="fixed_flow"?"selected":""}>指定流量から翼温度</option><option value="metal_limit" ${v.mode==="metal_limit"?"selected":""}>許容翼温度から必要流量（1流路）</option></select></label>`:""}<div class="cooling-circuit-grid">${Object.entries(bladeLabels[group]).map(([key,[title,unit]])=>`<label class="field">${title}<input type="number" step="any" id="${p+key}" aria-label="冷却流路${i+1} ${title}" value="${v[key]}"><span class="minor">${unit}</span></label>`).join("")}</div><p class="minor">${group==="thermal"?"面積はこの流路で冷却する全翼の合計です。入力した熱伝達率を使う等価並流モデルです。ガス側温度は合流前の絶対全温を等価温度に使用し、相対回復温度や3D局所最高温度は求めません。":"Euler仕事 w=ω²(β出口 r出口²−β入口 r入口²)。β=Cθ/U。軸からの仕事を冷却空気へ加え、全圧効率で圧力上昇を求めます。このモデルの注入位置はロータ後または出口ディフューザー後です。"}</p></div></details>`;}).join("");}
function readBlade(i,group){const p=`#b-${i}-${group}-`,v={enabled:$(p+"enabled").checked};if(group==="thermal")v.mode=$(p+"mode").value;for(const key of Object.keys(bladeLabels[group])){const raw=$(p+key).value;if(!raw.trim()||!Number.isFinite(Number(raw)))throw new Error("翼熱・ポンピングの数値を入力してください。");v[key]=Number(raw);}return v;}
function renderCooling(){renderCoolingBase();const c=current.result.cooling;if(!c)return;const rows=c.routes;$("#details").innerHTML+=panel("翼温度・内部伝熱・ポンピング",`<div class="panel-body"><p>ポンピング軸動力 <strong>${fmt((c.pumping_power_w||0)/1000,4)} kW</strong>。内部伝熱は主流から減らして冷却空気へ加え、直後の完全混合で相殺します。指定流量では内部伝熱だけでサイクル出力は変わりません。</p>${c.flow_sizing?`<div class="notice">流量逆算結果：流路${c.flow_sizing.circuit_index+1}、入口空気基準 ${fmt(c.flow_sizing.fraction*100,5)}%。${c.flow_sizing.status==="minimum_flow_satisfies_limit"?"指定下限で許容温度を満たします。":"許容温度を満たす流量を求めました。"}</div>`:""}<p class="minor">金属最高温度は等価並流セル両端の大きい方です。局所高温部・相対回復温度・冷却孔噴流は評価していません。熱伝達率・フィルム有効度は入力値です。</p></div><div class="table-wrap"><table><thead><tr><th>流路</th><th>ポンピング kW</th><th>ポンプ前Pt kPa</th><th>ポンプ後Pt kPa</th><th>翼伝熱 kW</th><th>冷却出口 K</th><th>熱交換後主流 K</th><th>翼金属最高 K</th><th>温度余裕 K</th><th>判定</th></tr></thead><tbody>${rows.map(r=>{const t=r.thermal;return `<tr><td>${esc(r.input.name)}</td><td class="num">${fmt((r.pumping_power_w||0)/1000,4)}</td><td class="num">${fmt(r.pre_pump_pressure_pa/1000,3)}</td><td class="num">${fmt(r.supply_total_pressure_pa/1000,3)}</td><td class="num">${fmt(t?t.heat_w/1000:null,4)}</td><td class="num">${fmt(t?.coolant_outlet_temperature_k,3)}</td><td class="num">${fmt(t?.gas_outlet_temperature_k,3)}</td><td class="num">${fmt(t?.metal_max_temperature_k,3)}</td><td class="num">${fmt(t?.metal_margin_k,3)}</td><td>${t?(t.within_metal_limit?"許容温度内":"許容温度超過"):"翼熱未使用"}</td></tr>`;}).join("")}</tbody></table></div>`);}
function bladeComparison(a,b){const rows=[];for(let i=0;i<Math.max(a.cooling?.circuits.length||0,b.cooling?.circuits.length||0);i++){for(const group of ["thermal","pumping"]){const x=a.cooling?.circuits[i]?.[group],y=b.cooling?.circuits[i]?.[group];if(!x?.enabled&&!y?.enabled)continue;for(const key of Object.keys(config.cooling_circuit_template[group]))if(x?.[key]!==y?.[key])rows.push([`流路${i+1} ${group==="thermal"?"翼熱":"ポンピング"} ${bladeLabels[group][key]?.[0]||({enabled:"使用",mode:"計算モード"}[key]||key)}`,x?.[key],y?.[key]]);}}return rows.length?panel("翼熱・ポンピング条件の差分",`<div class="table-wrap"><table><thead><tr><th>条件</th><th>現在</th><th>保存</th></tr></thead><tbody>${rows.map(([label,x,y])=>`<tr><td>${esc(label)}</td><td>${esc(String(x??"—"))}</td><td>${esc(String(y??"—"))}</td></tr>`).join("")}</tbody></table></div>`):"";}
$("#blade-sample").onclick=()=>{$("#cooling-sample").click();const v=readCooling();const c=v.circuits[1];c.name="動翼内部冷却";c.injection="after_rotor";c.thermal.enabled=true;c.thermal.gas_area_m2=.08;c.thermal.coolant_area_m2=.10;c.thermal.metal_limit_k=730;c.pumping.enabled=true;c.pumping.inlet_radius_m=.015;c.pumping.outlet_radius_m=.04;setCooling(v);markDirty();notify("翼熱・ポンピングの仮定サンプルを設定しました。再計算してください。");};
